WITH MF_BASE AS (
SELECT
      A.DIVISION_ID
    , A.DIVISION_ID                                         AS DIVISION_ID40
    , A.SCM_SITE_ID
    , A.SCM_SITE_ID                                         AS SCM_SITE_ID40
    , A.PLANT_SITE_ID
    , A.PROJECT_CODE
    , NVL(I.GROUP_ID,'/')                                  AS GROUP_ID
    , A.ITEM_ID
    , A.ITEM_ID                                             AS ITEM_ID40
    , A.INCOTERMS
    , A.FCST_TYPE
    , A.DOM_EXP
    , A.MEASURE
    , A.END_CUSTOMER
    , CASE WHEN (A.DIVISION_ID LIKE '81%' OR A.DIVISION_ID = '82')
           THEN A.END_CUSTOMER ELSE A.PROJECT_CODE END      AS END_CUSTOMER40
    , A.NICK_NAME
    , A.DMS_SALES
    , A.DMS_CUSTOMER
    , C.BASIS_YYYYMM                                        AS YYYYMM
    , C.BASIS_YYYYMM || C.ISO_WEEK                          AS YYYYMMWW
    , C.BASIS_YYYYMMDD                                      AS YYYYMMDD
    , C.DAYOFWEEK
    , A.CELL_MODEL                                          AS FORECAST_INFO_CELL_MODEL
    , A.DEPT_ID                                             AS TEAM_ID
    , A.DEPT_NAME_KO                                        AS TEAM_NAME_KO
    , A.ITEM_TYPE
    , A.PROJECT_NAME
    , A.PROJECT_OWNER
    , A.OWNER
    , A.BIZ_TYPE
    , A.SOLDTO_CUSTOMER
    , A.COUNTRY_NAME
    , A.CITY_NAME
    , A.PROJECT_STATUS
    , SI.PROJECT_S_OP_REPORT
    , A.ITEM_NAME
    , A.VMI_YN
    , A.CUST_GROUP
    , A.CUST_GROUP_DTL
    , A.APPLICATION
    , A.ROUTE
    , A.MDM_PROJECT_NAME
    , A.MIN_CAPACITY
    , A.FORECAST_INFO_BIZ_TYPE
    , A.CELL_TYPE
    , A.FORECAST_INFO_CELL_PACK_COUNT
    , A.FORECAST_INFO_ALL
    , A.FORECAST_INFO_SPEC
    , A.FORECAST_INFOR_VERSION
    , A.CELL_MODEL_NICK_NAME
    , CAST(CASE WHEN 'Y' = 'N'
                 AND A.MEASURE_GROUP NOT IN ('SFA','VMI_DIO','OVER_FCST','LESS_FCST','CFA','CFCR')
                 AND NVL(A.FORECAST_INFO_CELL_PACK_COUNT,1) <> 1
                THEN A.QTY * A.FORECAST_INFO_CELL_PACK_COUNT
                ELSE A.QTY END AS NUMBER(36,10)) AS QTY
    , CASE WHEN C2.MONTH_END_DATE IS NOT NULL THEN 'Y' ELSE 'N' END AS MONTH_END_YN
    , CASE WHEN C3.WEEK_END_DATE  IS NOT NULL THEN 'Y' ELSE 'N' END AS WEEK_END_YN
    , CASE
          WHEN MA.DEPT_ID IS NOT NULL
               AND A.MEASURE_GROUP NOT IN ('CUST_FCST_2','CUST_FCST_3','TMM_FCST')
               AND A.MEASURE = M1.SEGMENT2 THEN 'Y'
          WHEN '' = 'ADMIN'
               AND A.MEASURE_GROUP <> 'TMM_FCST'
               AND A.MEASURE = M1.SEGMENT2 THEN 'Y'
          WHEN A.MEASURE_GROUP = 'TMM_FCST'
               AND A.PROJECT_CODE = M2.SEGMENT2
               AND A.MEASURE = M1.SEGMENT2 THEN 'Y'
          ELSE 'N'
      END AS EDIT_FLAG
    , A.CELL_PER_CAR
    , A.CELL_PER_MODULE
    , A.MODULE_PER_CAR
    , A.SORT_ORDER_NO
    , A.MEASURE_GROUP
    , A.ENERGE
    , A.CELL_QUANTITY
    , 'N'                                                 AS NEW_FLAG
    , CASE WHEN A.DIVISION_ID = '40'
           THEN TO_CHAR(CAST(VM.VMI_STD_DIO AS NUMBER))
           ELSE VM.VMI_VAL END                             AS VMI_STD_DIO
    , NVL(B1.ATTR1, B2.ATTR1)                              AS ATTR1
    , NVL(BK.BUCKET,'0000000')                           AS BUCKET
    , 'N'                               AS AS_YN
    , CASE WHEN 'N' = 'Y' THEN NVL(X.DISPLAY_SEQ,999) ELSE 999 END AS SORT_KEY
    , NVL(A.AS_FROM_SITE,'/')                            AS AS_FROM_SITE
    , CASE WHEN A.CREATE_DATE IS NULL OR NVL(A.CREATE_DATE,'')    = '' THEN ' ' ELSE A.CREATE_DATE    END AS LAST_UPDATE_DATE
    , CASE WHEN A.LAST_UPDATED_BY IS NULL OR NVL(A.LAST_UPDATED_BY,'/')= '/' THEN ' ' ELSE A.LAST_UPDATED_BY END AS LAST_UPDATED_BY
    , CASE WHEN A.SENDER_CODE IS NULL OR NVL(A.SENDER_CODE,'/')    = '/' THEN ' ' ELSE A.SENDER_CODE    END AS SENDER_CODE
    , CASE WHEN A.SENDER_NAME IS NULL OR NVL(A.SENDER_NAME,'/')    = '/' THEN ' ' ELSE A.SENDER_NAME    END AS SENDER_NAME
    , A.NOTATION
FROM SCM_MGR.GT_DMF0003_MKT_FCST_DATA A
INNER JOIN SCM_MGR.SCM_SYS_CALENDAR_M C
  ON  C.BASIS_YYYYMMDD = A.YYYYMMDD
LEFT OUTER JOIN SCM_MGR.SCM_MST_SITE_ITEM SI
  ON  A.DIVISION_ID  = SI.DIVISION_ID
  AND A.PROJECT_CODE = SI.PROJECT_CODE
  AND A.SCM_SITE_ID  = SI.SCM_SITE_ID
  AND A.ITEM_ID      = SI.ITEM_ID
LEFT OUTER JOIN SCM_MGR.SCP_MST_ITEM_GROUP_DETAIL I
  ON  A.DIVISION_ID = I.DIVISION_ID
  AND A.PROJECT_CODE = I.PROJECT_CODE
  AND A.ITEM_ID      = I.ITEM_ID
LEFT OUTER JOIN SCM_MGR.GT_DMF0003_CAL_MONTH_END C2
  ON  A.YYYYMMDD = C2.MONTH_END_DATE
LEFT OUTER JOIN SCM_MGR.GT_DMF0003_CAL_WEEK_END C3
  ON  A.YYYYMMDD = C3.WEEK_END_DATE
LEFT OUTER JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL X
  ON  A.SCM_SITE_ID = X.SEGMENT1 AND X.LOOKUP_TYPE = 'AS_SITE_PLANT'
LEFT JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL M1
  ON  A.DIVISION_ID = M1.SEGMENT1
  AND A.MEASURE     = M1.SEGMENT2
  AND M1.LOOKUP_TYPE = 'MKT_FCST_MEASURE'
  AND M1.SEGMENT5    = 'Y'
  AND M1.VALID_YN    = 'Y'
LEFT JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL M2
  ON  A.DIVISION_ID  = M2.SEGMENT1
  AND A.PROJECT_CODE = M2.SEGMENT2
  AND 'zz_diag_dmf0003' = M2.SEGMENT4
  AND M2.LOOKUP_TYPE = 'TMM_MEASURE_ADMIN'
  AND M2.VALID_YN    = 'Y'
LEFT JOIN SCM_MGR.GT_DMF0003_VMI_DIO VM
  ON  A.ITEM_ID     = CASE WHEN '40' = '40' THEN VM.KEY_JOIN ELSE A.ITEM_ID END
  AND ( '40' = '40'  
        OR A.SCM_SITE_ID = VM.KEY_JOIN )
LEFT OUTER JOIN SCM_MGR.GT_DMF0003_T_SSP_SYNC B1
  ON  A.DIVISION_ID  = B1.DIVISION_ID AND A.PROJECT_CODE = B1.PROJECT_CODE
  AND A.SCM_SITE_ID  = B1.SCM_SITE_ID  AND A.ITEM_ID     = B1.ITEM_ID
  AND A.DOM_EXP      = B1.DOM_EXP       AND A.FCST_TYPE   = B1.FCST_TYPE
  AND A.INCOTERMS    = B1.INCOTERMS     AND A.MEASURE     = 'MKT_FCST_RP'
LEFT OUTER JOIN SCM_MGR.GT_DMF0003_T_BNP B2
  ON  A.DIVISION_ID  = B2.DIVISION_ID AND A.PROJECT_CODE = B2.PROJECT_CODE
  AND A.SCM_SITE_ID  = B2.SCM_SITE_ID  AND A.ITEM_ID     = B2.ITEM_ID
  AND A.DOM_EXP      = B2.DOM_EXP       AND A.FCST_TYPE   = B2.FCST_TYPE
  AND A.INCOTERMS    = B2.INCOTERMS     AND A.MEASURE     = 'BNPIn'
LEFT OUTER JOIN (
    SELECT DIVISION_ID, SCM_SITE_ID, INCOTERMS
         , NVL(V_SUN,0)||NVL(V_MON,0)||NVL(V_TUE,0)||NVL(V_WED,0)
           ||NVL(V_THU,0)||NVL(V_FRI,0)||NVL(V_SAT,0)              AS BUCKET
    FROM  (SELECT DIVISION_ID, SCM_SITE_ID, INCOTERMS, YYYYMMDD
                , CASE WHEN BUCKET_PER = 'Y' THEN 1 ELSE 0 END AS BUCKET_PER
           FROM  SCM_MGR.DM_MST_BUCKET_CONVERSION
           WHERE DIVISION_ID = '40') A
    PIVOT (MAX(BUCKET_PER) FOR YYYYMMDD
           IN ('SUN' AS V_SUN,'MON' AS V_MON,'TUE' AS V_TUE,'WED' AS V_WED,
               'THU' AS V_THU,'FRI' AS V_FRI,'SAT' AS V_SAT))
) BK ON A.DIVISION_ID = BK.DIVISION_ID
     AND A.SCM_SITE_ID = BK.SCM_SITE_ID
     AND A.INCOTERMS   = BK.INCOTERMS
LEFT OUTER JOIN (
    SELECT LOOK.SEGMENT3 AS DEPT_ID
    FROM   SCM_MGR.SCM_ADM_USER_M USR
    JOIN   SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL LOOK
      ON   USR.DEPT_ID = LOOK.SEGMENT1
     AND   LOOK.LOOKUP_TYPE = 'PM_TEAM_MAPPING'
     AND   LOOK.VALID_YN    = 'Y'
    WHERE  USR.USER_ID = 'zz_diag_dmf0003'
    UNION
    SELECT DEPT_ID FROM SCM_MGR.SCM_ADM_USER_M WHERE USER_ID = 'zz_diag_dmf0003'
) MA ON A.DEPT_ID = MA.DEPT_ID
WHERE 1=1 AND 1=1
)
SELECT DIVISION_ID, DIVISION_ID40, END_CUSTOMER, END_CUSTOMER40, SCM_SITE_ID40, SCM_SITE_ID, PROJECT_CODE, PROJECT_NAME, PROJECT_OWNER, GROUP_ID, ITEM_ID, ITEM_ID40, NICK_NAME, INCOTERMS, FCST_TYPE, DOM_EXP, PLANT_SITE_ID, EDIT_FLAG, NEW_FLAG, BUCKET, MEASURE_GROUP, VMI_STD_DIO, ATTR1, AS_YN, SORT_KEY, AS_FROM_SITE, MEASURE,NOTATION, SORT_ORDER_NO, M_202610 AS M_202610,W_20261040 AS W_20261040,D_20261001 AS D_20261001,D_20261002 AS D_20261002,D_20261003 AS D_20261003,D_20261004 AS D_20261004,W_20261041 AS W_20261041,D_20261005 AS D_20261005,D_20261006 AS D_20261006,D_20261007 AS D_20261007,D_20261008 AS D_20261008,D_20261009 AS D_20261009,D_20261010 AS D_20261010,D_20261011 AS D_20261011,W_20261042 AS W_20261042,D_20261012 AS D_20261012,D_20261013 AS D_20261013,D_20261014 AS D_20261014,D_20261015 AS D_20261015,D_20261016 AS D_20261016,D_20261017 AS D_20261017,D_20261018 AS D_20261018,W_20261043 AS W_20261043,D_20261019 AS D_20261019,D_20261020 AS D_20261020,D_20261021 AS D_20261021,D_20261022 AS D_20261022,D_20261023 AS D_20261023,D_20261024 AS D_20261024,D_20261025 AS D_20261025,W_20261044 AS W_20261044,D_20261026 AS D_20261026,D_20261027 AS D_20261027,D_20261028 AS D_20261028,D_20261029 AS D_20261029,D_20261030 AS D_20261030,D_20261031 AS D_20261031,M_202611 AS M_202611,W_20261144 AS W_20261144,D_20261101 AS D_20261101,W_20261145 AS W_20261145,D_20261102 AS D_20261102,D_20261103 AS D_20261103,D_20261104 AS D_20261104,D_20261105 AS D_20261105,D_20261106 AS D_20261106,D_20261107 AS D_20261107,D_20261108 AS D_20261108,W_20261146 AS W_20261146,D_20261109 AS D_20261109,D_20261110 AS D_20261110,D_20261111 AS D_20261111,D_20261112 AS D_20261112,D_20261113 AS D_20261113,D_20261114 AS D_20261114,D_20261115 AS D_20261115,W_20261147 AS W_20261147,D_20261116 AS D_20261116,D_20261117 AS D_20261117,D_20261118 AS D_20261118,D_20261119 AS D_20261119,D_20261120 AS D_20261120,D_20261121 AS D_20261121,D_20261122 AS D_20261122,W_20261148 AS W_20261148,D_20261123 AS D_20261123,D_20261