    FROM   MF_BASE F
    UNION ALL
    SELECT DIVISION_ID, DIVISION_ID40, END_CUSTOMER, END_CUSTOMER40, SCM_SITE_ID40, SCM_SITE_ID, PROJECT_CODE, PROJECT_NAME, PROJECT_OWNER, GROUP_ID, ITEM_ID, ITEM_ID40, NICK_NAME, INCOTERMS, FCST_TYPE, DOM_EXP, PLANT_SITE_ID, EDIT_FLAG, NEW_FLAG, BUCKET, MEASURE_GROUP, VMI_STD_DIO, ATTR1, AS_YN, SORT_KEY, AS_FROM_SITE, MEASURE,NOTATION, F.SORT_ORDER_NO, 'W_' || F.YYYYMMWW AS YYYYMMDD
         , CASE WHEN F.MEASURE IN ('BALANCE','VMI_Inv','AS_Inv')
                THEN CASE WHEN F.WEEK_END_YN = 'Y' THEN SUM(F.QTY) ELSE 0 END
                ELSE SUM(F.QTY) END AS QTY
    FROM   MF_BASE F
    WHERE  F.QTY <> (CASE WHEN F.MEASURE IN
                    ('CUST_FCST','CUST_FCST_EDI','Immidiate','Planning_Forecast',
                     'Commercial_Agreement','Firm_Temp','Manumacturing_Material_Temp',
                     'Material_Temp','Backorder','CUST_FCST_EDI_ORG',
                     'Immidiate[Org.]','Planning_Forecast[Org.]',
                     'Commercial_Agreement[Org.]','Firm_Temp[Org.]',
                     'Manumacturing_Material_Temp[Org.]','Material_Temp[Org.]',
                     'Backorder[Org.]') THEN -9999999999 ELSE 0 END)
    GROUP BY DIVISION_ID, DIVISION_ID40, END_CUSTOMER, END_CUSTOMER40, SCM_SITE_ID40, SCM_SITE_ID, PROJECT_CODE, PROJECT_NAME, PROJECT_OWNER, GROUP_ID, ITEM_ID, ITEM_ID40, NICK_NAME, INCOTERMS, FCST_TYPE, DOM_EXP, PLANT_SITE_ID, EDIT_FLAG, NEW_FLAG, BUCKET, MEASURE_GROUP, VMI_STD_DIO, ATTR1, AS_YN, SORT_KEY, AS_FROM_SITE, MEASURE,NOTATION, F.SORT_ORDER_NO, F.YYYYMMWW, F.WEEK_END_YN
    UNION ALL
    SELECT DIVISION_ID, DIVISION_ID40, END_CUSTOMER, END_CUSTOMER40, SCM_SITE_ID40, SCM_SITE_ID, PROJECT_CODE, PROJECT_NAME, PROJECT_OWNER, GROUP_ID, ITEM_ID, ITEM_ID40, NICK_NAME, INCOTERMS, FCST_TYPE, DOM_EXP, PLANT_SITE_ID, EDIT_FLAG, NEW_FLAG, BUCKET, MEASURE_GROUP, VMI_STD_DIO, ATTR1, AS_YN, SORT_KEY, AS_FROM_SITE, MEASURE,NOTATION, F.SORT_ORDER_NO, 'M_' || F.YYYYMM AS YYYYMMDD
         , CASE WHEN F.MEASURE IN ('BALANCE','VMI_Inv','AS_Inv')
                THEN CASE WHEN F.MONTH_END_YN = 'Y' THEN SUM(F.QTY) ELSE 0 END
                ELSE SUM(F.QTY) END AS QTY
    FROM   MF_BASE F
    WHERE  F.QTY <> (CASE WHEN F.MEASURE IN
                    ('CUST_FCST','CUST_FCST_EDI','Immidiate','Planning_Forecast',
                     'Commercial_Agreement','Firm_Temp','Manumacturing_Material_Temp',
