                     'Commercial_Agreement[Org.]','Firm_Temp[Org.]',
                     'Manumacturing_Material_Temp[Org.]','Material_Temp[Org.]',
                     'Backorder[Org.]') THEN -9999999999 ELSE 0 END)
    GROUP BY DIVISION_ID, DIVISION_ID40, END_CUSTOMER, END_CUSTOMER40, SCM_SITE_ID40, SCM_SITE_ID, PROJECT_CODE, PROJECT_NAME, PROJECT_OWNER, GROUP_ID, ITEM_ID, ITEM_ID40, NICK_NAME, INCOTERMS, FCST_TYPE, DOM_EXP, PLANT_SITE_ID, EDIT_FLAG, NEW_FLAG, BUCKET, MEASURE_GROUP, VMI_STD_DIO, ATTR1, AS_YN, SORT_KEY, AS_FROM_SITE, MEASURE,NOTATION, F.SORT_ORDER_NO, F.YYYYMM, F.MONTH_END_YN
) F
